LANDMARKS.hkpeakgalleria = {zh:'山顶广场', en:'The Peak Galleria', cat:'new', r:RR, h:16, lt:{m:1, c:'#ffe6c4', k:0.5, fh:4.5, cw:3.2},
  build(){
    const g = new THREE.Group(), gl = mkGround(LAT, LON, RR).gl, B = mkBatch();
    const WALL = {c:'#d8d2c6', m:1, fh:4.5, cw:3.2}, GLS = {c:'#55646e', glow:'#ffe6c4', gk:0.55}, ROOF = {c:'#bdb7ab', m:0, lk:0.15}, RAIL = '#eeeeea', ST = {c:'#a69e90', m:0, lk:0.2}, GRN = '#6f8a5c';
    const C = 5, bb = bbox(PG), cells = new Map(), key = (i, j) => i + ',' + j;
    for (let x = bb[0]; x < bb[2]; x += C) for (let z = bb[1]; z < bb[3]; z += C){ const cx = x + C/2, cz = z + C/2; if (!inPoly(PG, cx, cz)) continue;
      const gr = gl(cx, cz), lv = Math.ceil((gr + 10.5)/4.5)*4.5; cells.set(key(Math.round((x - bb[0])/C), Math.round((z - bb[1])/C)), {cx, cz, gr, lv}); }
    for (const [k, c] of cells){ const [i, j] = k.split(',').map(Number);
      obox(B.a(WALL), c.cx, c.cz, 0, C, C, c.gr - 2, c.lv); obox(B.a(ROOF), c.cx, c.cz, 0, C, C, c.lv, c.lv + 0.2);
      for (const [di, dj, ox, oz] of [[1, 0, C/2, 0], [-1, 0, -C/2, 0], [0, 1, 0, C/2], [0, -1, 0, -C/2]]){ const n = cells.get(key(i + di, j + dj)), lo = n ? n.lv : c.gr;
        if (lo < c.lv - 1.5){ const a = B.a(GLS), y0 = Math.max(lo, c.gr) + 0.6, y1 = c.lv - 0.9; if (y1 > y0 + 0.5){ const x = c.cx + ox*1.02, z = c.cz + oz*1.02, h = C/2 - 0.2; if (ox) quad(a, [x, y0, z - h], [x, y0, z + h], [x, y1, z + h], [x, y1, z - h]); else quad(a, [x - h, y0, z], [x + h, y0, z], [x + h, y1, z], [x - h, y1, z]); }
          const rl = B.a(RAIL), x = c.cx + ox*0.96, z = c.cz + oz*0.96, h = C/2; if (ox) quad(rl, [x, c.lv + 0.2, z - h], [x, c.lv + 0.2, z + h], [x, c.lv + 1.25, z + h], [x, c.lv + 1.25, z - h]); else quad(rl, [x - h, c.lv + 0.2, z], [x + h, c.lv + 0.2, z], [x + h, c.lv + 1.25, z], [x - h, c.lv + 1.25, z]); } } }
    // planters and a few trees on the terraces
    let n = 0; for (const [, c] of cells){ if (((Math.round(c.cx*7 + c.cz*13) % 11) + 11) % 11 === 0 && n < 14){ LCyl(g, 0.25, 0.35, 2.2, c.cx, c.lv + 0.2, c.cz, '#5b4a3a', 6); LSph(g, 1.6, c.cx, c.lv + 3.2, c.cz, GRN, 0.85, 8); n++; } }
    B.flush(g); return g; }};
