    fbox(B.a(GR2), f, ANG, 0, 0, L, W, 0, 0.8);
    fbox(B.a(GR), f, ANG, 0, 0, L - 7, W - 7, 0.8, 15.6);                           // the house behind the verandahs
    // ground floor: granite piers with flat (segmental) arches on the perimeter
    const nU = 15, nV = 5, pier = B.a(GR);
    for (let i = 0; i <= nU; i++){ const u = -L/2 + 0.7 + (L - 1.4)*i/nU; for (const v of [-W/2 + 0.7, W/2 - 0.7]) fbox(pier, f, ANG, u, v, 1.4, 1.4, 0.8, 5.6); }
    for (let i = 1; i < nV; i++){ const v = -W/2 + 0.7 + (W - 1.4)*i/nV; for (const u of [-L/2 + 0.7, L/2 - 0.7]) fbox(pier, f, ANG, u, v, 1.4, 1.4, 0.8, 5.6); }
    fbox(B.a(GR), f, ANG, 0, 0, L, W, 4.7, 5.9);                                     // the lintel band over the arches and the first floor
    // upper floors: Doric then Ionic columns, floors, balustrades
    for (const [y0, y1, r] of [[5.9, 10.2, 0.36], [10.8, 15.0, 0.3]]){
      const col = B.a(WH);
      for (let i = 0; i <= nU; i++){ const u = -L/2 + 0.7 + (L - 1.4)*i/nU; for (const v of [-W/2 + 0.7, W/2 - 0.7]){ const c = f(u, v); colB(col, c[0], c[1], r, y0, y1, 8); } }
      for (let i = 1; i < nV; i++){ const v = -W/2 + 0.7 + (W - 1.4)*i/nV; for (const u of [-L/2 + 0.7, L/2 - 0.7]){ const c = f(u, v); colB(col, c[0], c[1], r, y0, y1, 8); } }
      fbox(B.a(WH), f, ANG, 0, 0, L, W, y1, y1 + 0.6);
      for (const v of [-W/2 + 0.7, W/2 - 0.7]) fbox(B.a(WH), f, ANG, 0, v, L - 1.4, 0.2, y0, y0 + 1.0);
      for (const u of [-L/2 + 0.7, L/2 - 0.7]) fbox(B.a(WH), f, ANG, u, 0, 0.2, W - 1.4, y0, y0 + 1.0);
    }
    fbox(B.a(WH), f, ANG, 0, 0, L + 0.4, W + 0.4, 15.6, 16.4);
